  | { status: 'exists' }
  | { status: 'not_found' }
  | { status: 'unreachable' };

export async function createBoardRequest(): Promise<CreateResponse> {
  let response: Response;
  try {
    response = await fetch('/api/boards', { method: 'POST' });
  } catch {
    return { kind: 'failed' };
  }
  if (response.status === 201) {
    const body = (await response.json().catch(() => null)) as { id?: unknown } | null;
    if (typeof body?.id === 'string' && body.id.length > 0) return { kind: 'created', id: body.id };
    return { kind: 'failed' };
  }
  if (response.status === 429) return { kind: 'rate_limited' };
  return { kind: 'failed' };
}

/** Existence check for a link code. Anything other than 200/404 is unreachable. */
export async function checkBoard(id: string): Promise<CheckResponse> {
  let response: Response;
  try {
    response = await fetch(`/api/boards/${encodeURIComponent(id)}`);
  } catch {
    return { status: 'unreachable' };
  }
  if (response.status === 200) return { status: 'exists' };
  if (response.status === 404) return { status: 'not_found' };
  return { status: 'unreachable' };
}
// Minimal History-API router: '/' home, '/b/:id' board, anything else not found.

import { useSyncExternalStore } from 'react';

export type Route =
  | { name: 'home' }
  | { name: 'board'; id: string }
  | { name: 'not_found' };

const listeners = new Set<() => void>();

if (typeof window !== 'undefined') {
  window.addEventListener('popstate', () => {
    for (const listener of listeners) listener();
  });
}

export function parsePath(pathname: string): Route {
  if (pathname === '/' || pathname === '') return { name: 'home' };
  const match = /^\/b\/([^/]+)\/?$/.exec(pathname);
  if (match) {
    let id = match[1]!;
    try {
      id = decodeURIComponent(id);
    } catch {
      // keep the raw value: it will fail validation and render not-found
    }
    return { name: 'board', id };
  }
  return { name: 'not_found' };
}

function subscribe(callback: () => void): () => void {
  listeners.add(callback);
  return () => {
    listeners.delete(callback);
  };
}

function currentPath(): string {
  return typeof window === 'undefined' ? '/' : window.location.pathname;
}

/** pushState + notify, so navigation re-renders without a page load. */
export function navigate(path: string): void {
  window.history.pushState({}, '', path);
  for (const listener of listeners) listener();
}

export function useRoute(): Route {
  const pathname = useSyncExternalStore(subscribe, currentPath, () => '/');
  return parsePath(pathname);
}
// Home page: product name, one sentence, and one call to action. The create
// action is exported so NotFoundPage's "Create a new board" reuses it verbatim.

import { useCallback, useEffect, useRef, useState } from 'react';
import { createBoardRequest } from '../api';
import { navigate } from '../router';

export const ERROR_CREATE_MESSAGE = "Couldn't create a board. Please try again.";
export const ERROR_RATE_LIMIT_MESSAGE = "You're creating boards too quickly. Wait a minute and try again.";

export type CreatePhase = 'idle' | 'creating' | 'failed' | 'rate_limited';

/** Create a board then navigate to it; failures become page state, never throws. */
export function useCreateBoardAction() {
  const [phase, setPhase] = useState<CreatePhase>('idle');
  const mounted = useRef(true);

  useEffect(() => {
    mounted.current = true;
    return () => {
      mounted.current = false;
    };
  }, []);

  const create = useCallback(async (): Promise<void> => {
    setPhase('creating');
    const response = await createBoardRequest();
    if (!mounted.current) return;
    if (response.kind === 'created') {
      navigate(`/b/${encodeURIComponent(response.id)}`);
      return;
    }
    setPhase(response.kind === 'rate_limited' ? 'rate_limited' : 'failed');
  }, []);

  return { phase, create };
}

export function HomePage() {
  const { phase, create } = useCreateBoardAction();
  const creating = phase === 'creating';
  return (
    <main className="page home-page">
      <div className="home-card">
        <h1 className="wordmark">vidi6</h1>
        <p className="tagline">A shared board for thinking together</p>
        <button
          type="button"
          className="create-board-button"
          disabled={creating}
          aria-busy={creating}
          onClick={() => void create()}
        >
          {creating ? 'Creating…' : 'Create a board'}
        </button>
        {phase === 'failed' || phase === 'rate_limited' ? (
          <p className="home-error" role="alert">
            {phase === 'failed' ? ERROR_CREATE_MESSAGE : ERROR_RATE_LIMIT_MESSAGE}
          </p>
        ) : null}
      </div>
    </main>
  );
}
// Board not found: shown for unknown codes, malformed codes and dead links.
// Nothing is created by *opening* the link; the Create a new board button reuses
// HomePage's create action, which creates a board at a brand-new address.

import type { MouseEvent } from 'react';
import { navigate } from '../router';
import {
  ERROR_CREATE_MESSAGE,
  ERROR_RATE_LIMIT_MESSAGE,
  useCreateBoardAction,
} from './HomePage';

function HomeLink() {
  const onClick = (event: MouseEvent<HTMLAnchorElement>): void => {
    if (event.metaKey || event.ctrlKey || event.shiftKey || event.button !== 0) return;
    event.preventDefault();
    navigate('/');
  };
  return (
    <a className="home-link" href="/" onClick={onClick}>
      Back to vidi6
    </a>
  );
}

export function NotFoundPage() {
  const { phase, create } = useCreateBoardAction();
  const creating = phase === 'creating';
  return (
    <main className="page not-found-page">
      <div className="not-found-card">
        <h1 className="not-found-heading">Board not found</h1>
        <p className="not-found-body">Check the link, or ask the person who shared it to send it again.</p>
        <button
          type="button"
          className="create-board-button"
          disabled={creating}
          aria-busy={creating}
          onClick={() => void create()}
        >
          {creating ? 'Creating…' : 'Create a new board'}
        </button>
        <p className="not-found-home">
          <HomeLink />
        </p>
        {phase === 'failed' ? (
          <p className="home-error" role="alert">
            {ERROR_CREATE_MESSAGE}
          </p>
        ) : null}
        {phase === 'rate_limited' ? (
          <p className="home-error" role="alert">
            {ERROR_RATE_LIMIT_MESSAGE}
          </p>
        ) : null}
      </div>
    </main>
  );
}

// Board page: validates the link code, asks the service whether the board
// exists, then mounts the board (and only then opens its room socket).
// States: Checking -> Ready | NotFound | Unreachable (retrying with exponential
// backoff). A malformed code never produces a request.

import { useEffect, useState } from 'react';
import { checkBoard } from '../api';
import { isValidBoardId } from '../../shared/board-id';
import { BOARD_CHECK_RETRY_BASE_MS, RECONNECT_MAX_BACKOFF_MS } from '../../shared/config';
import { BoardWorkspace } from '../board/BoardWorkspace';
import { NotFoundPage } from './NotFoundPage';

export type BoardPagePhase = 'checking' | 'ready' | 'not_found' | 'unreachable';

export function BoardPage({ id }: { id: string }) {
  const valid = isValidBoardId(id);
  const [phase, setPhase] = useState<BoardPagePhase>(valid ? 'checking' : 'not_found');

  useEffect(() => {
    if (!valid) return;
    let cancelled = false;
    let timer: ReturnType<typeof setTimeout> | undefined;
    let attempt = 0;

    const run = async (): Promise<void> => {
      const result = await checkBoard(id);
      if (cancelled) return;
      if (result.status === 'exists') {
        setPhase('ready');
        return;
      }
      if (result.status === 'not_found') {
        setPhase('not_found');
        return;
      }
      setPhase('unreachable');
      const delay = Math.min(BOARD_CHECK_RETRY_BASE_MS * 2 ** attempt, RECONNECT_MAX_BACKOFF_MS);
      attempt += 1;
      timer = setTimeout(() => void run(), delay);
    };

    void run();
    return () => {
      cancelled = true;
      if (timer) clearTimeout(timer);
    };
  }, [id, valid]);

  if (phase === 'checking') {
    return (
      <main className="page board-checking">
        <p role="status">Opening board…</p>
      </main>
    );
  }
  if (phase === 'not_found') return <NotFoundPage />;
  if (phase === 'unreachable') {
    return (
      <main className="page board-unreachable">
        <p role="status">{"Couldn't reach vidi6. Retrying…"}</p>
      </main>
    );
  }
  return <BoardWorkspace boardId={id} />;
}
// Share button + panel (story 5). Copy uses the async clipboard API; when that
// is unavailable or denied, the link is left selected in the field with a manual
// copy instruction, so sharing never dead-ends.

import { useCallback, useEffect, useRef, useState } from 'react';
import { LINK_COPIED_MS } from '../../shared/config';

export function boardLink(origin: string, id: string): string {
  return `${origin}/b/${id}`;
}

export function SharePanel({ boardId }: { boardId: string }) {
  const [open, setOpen] = useState(false);
  const [copied, setCopied] = useState(false);
  const [manual, setManual] = useState(false);
  const shareRef = useRef<HTMLButtonElement>(null);
  const panelRef = useRef<HTMLDivElement>(null);
  const inputRef = useRef<HTMLInputElement>(null);
  const timer = useRef<ReturnType<typeof setTimeout> | undefined>(undefined);

  const link = boardLink(window.location.origin, boardId);

  useEffect(
    () => () => {
      if (timer.current) clearTimeout(timer.current);
    },
    [],
  );

  const close = useCallback((): void => {
    setOpen(false);
    setManual(false);
    shareRef.current?.focus(); // focus returns to the Share button
  }, []);

  useEffect(() => {
    if (!open) return;
    const onPointerDown = (event: PointerEvent): void => {
      const target = event.target as Node | null;
      if (!target) return;
      if (panelRef.current?.contains(target) || shareRef.current?.contains(target)) return;
      close();
    };
    const onKeyDown = (event: KeyboardEvent): void => {
      if (event.key === 'Escape') {
        event.preventDefault();
        close();
      }
    };
    document.addEventListener('pointerdown', onPointerDown, true);
    document.addEventListener('keydown', onKeyDown);
    return () => {
      document.removeEventListener('pointerdown', onPointerDown, true);
      document.removeEventListener('keydown', onKeyDown);
    };
  }, [open, close]);

  const copy = useCallback(async (): Promise<void> => {
    let written = false;
    try {
      if (navigator.clipboard?.writeText) {
        await navigator.clipboard.writeText(link);
        written = true;
      }
    } catch {
      written = false;
    }
    if (written) {
      setManual(false);
      setCopied(true);
      if (timer.current) clearTimeout(timer.current);
      timer.current = setTimeout(() => setCopied(false), LINK_COPIED_MS);
      return;
    }
    setManual(true);
    inputRef.current?.focus();
    inputRef.current?.select();
  }, [link]);

  return (
    <div className="share-panel">
      <button
        type="button"
        ref={shareRef}
        className="share-button"
        aria-haspopup="dialog"
        aria-expanded={open}
        onClick={() => (open ? close() : setOpen(true))}
      >
        Share
      </button>
      {open ? (
        <div className="share-panel-body" role="dialog" aria-label="Share board" ref={panelRef}>
          <p className="share-note">Anyone with this link can view and edit this board.</p>
          <input
            ref={inputRef}
            className="share-link"
            readOnly
            value={link}
            aria-label="Board link"
            onFocus={(event) => event.currentTarget.select()}
            onClick={(event) => event.currentTarget.select()}
          />
          <button type="button" className="copy-link-button" onClick={() => void copy()}>
            {copied ? 'Link copied' : 'Copy link'}
          </button>
          {manual ? (
            <p className="manual-copy" role="status">
              Press Ctrl+C (Cmd+C on Mac) to copy
            </p>
          ) : null}
          <button type="button" className="share-close" aria-label="Close" onClick={close}>
            ×
          </button>
        </div>
      ) : null}
    </div>
  );
}
// Route switch. One screen at a time; the board screen is keyed by id so opening
// a different link remounts it.

import { useRoute } from './router';
import { HomePage } from './pages/HomePage';
import { BoardPage } from './pages/BoardPage';
import { NotFoundPage } from './pages/NotFoundPage';

export function App() {
  const route = useRoute();
  if (route.name === 'home') return <HomePage />;
  if (route.name === 'board') return <BoardPage key={route.id} id={route.id} />;
  return <NotFoundPage />;
}

